"""
File-based inter-agent messaging system.

Messages are stored as append-only JSONL files at
``~/.qbraid/inboxes/<session-id>.jsonl``.
"""

from __future__ import annotations

import json
import logging
import os
import time
from contextlib import contextmanager
from pathlib import Path
from typing import TYPE_CHECKING, Generator, Iterator, Optional

from .constants import INBOXES_DIR, TRANSCRIPT_POLL_INTERVAL_S
from .exceptions import AgentMessagingError
from .schemas import AgentMessage, MessageType
from .types import can_message

try:
    import fcntl  # POSIX only

    _HAS_FCNTL = True
except ImportError:  # pragma: no cover — Windows
    _HAS_FCNTL = False

if TYPE_CHECKING:
    from .registry import AgentSessionRegistryManager

logger = logging.getLogger(__name__)


def _inbox_path(session_id: str) -> Path:
    """Return the inbox file path for a session, creating the directory if needed.

    Args:
        session_id: The target session's identifier.

    Returns:
        Path to ``~/.qbraid/inboxes/<session-id>.jsonl``.
    """
    inbox_dir = Path(INBOXES_DIR)
    inbox_dir.mkdir(parents=True, exist_ok=True)
    return inbox_dir / f"{session_id}.jsonl"


@contextmanager
def _inbox_lock(session_id: str) -> Iterator[None]:
    """Serialize concurrent writers to one session's inbox.

    Two writers matter:
      * ``send_message`` (append) racing with ``mark_read`` (read-modify-rewrite):
        without a lock, an append landing between mark_read's read and its
        rewrite would be silently dropped by the rewrite.
      * ``mark_read`` racing another ``mark_read``: last-writer-wins on the
        rewrite drops one caller's updates.

    Readers (``read_inbox``, ``watch_inbox``) intentionally lock-free — worst
    case they observe stale data during a rewrite, which is acceptable.

    Uses ``fcntl.flock`` on POSIX and no-ops on Windows (``msvcrt.locking``
    has no clean whole-file idiom, and the CLI is rarely run with concurrent
    writers on Windows). The lock is held on a sidecar ``.lock`` file so
    ``fcntl.flock`` on the JSONL itself isn't required (avoids interfering
    with readers that open the same fd).
    """
    if not _HAS_FCNTL:
        yield
        return

    lock_path = _inbox_path(session_id).with_suffix(".lock")
    # Open in append mode so the file is created if absent without truncating.
    with open(str(lock_path), "a", encoding="utf-8") as lock_fh:
        try:
            fcntl.flock(lock_fh.fileno(), fcntl.LOCK_EX)
            yield
        finally:
            try:
                fcntl.flock(lock_fh.fileno(), fcntl.LOCK_UN)
            except OSError:  # pragma: no cover — best-effort release
                pass


def send_message(
    from_session_id: str,
    to_session_id: str,
    text: str,
    message_type: str = "message",
    registry: Optional[AgentSessionRegistryManager] = None,
    validate_permissions: bool = True,
) -> AgentMessage:
    """Send a message from one agent session to another.

    The message is appended as a JSON line to the target session's inbox file
    at ``~/.qbraid/inboxes/<to_session_id>.jsonl``.

    Args:
        from_session_id: Sender session identifier.
        to_session_id: Target session identifier.
        text: Message body.
        message_type: One of the ``MessageType`` values (default ``"message"``).
        registry: Optional registry manager used for permission validation.
        validate_permissions: When *True* and *registry* is provided, enforce
            agent-type permission rules before delivering the message.

    Returns:
        The created ``AgentMessage``.

    Raises:
        AgentMessagingError: If the sender is not permitted to message the target.
    """
    if validate_permissions and registry is not None:
        try:
            sender = registry.get_session(from_session_id)
            target = registry.get_session(to_session_id)
        except Exception as exc:
            raise AgentMessagingError(
                f"Cannot resolve sessions for permission check: {exc}"
            ) from exc

        sender_type = sender.agent_type or "worker"
        target_type = target.agent_type or "worker"
        same_team = (
            sender.team_id is not None
            and target.team_id is not None
            and sender.team_id == target.team_id
        )
        is_parent = sender.parent_session_id == to_session_id

        if not can_message(sender_type, target_type, same_team=same_team, is_parent=is_parent):
            raise AgentMessagingError(
                f"Agent type '{sender_type}' is not permitted to message "
                f"agent type '{target_type}'"
            )

        # Cross-host messaging is not implemented — inboxes are per-host
        # JSONL files at ~/.qbraid/inboxes/. If we wrote to the local
        # inbox for a session that lives on a different compute host the
        # target would never see it. Fail loudly rather than silently
        # dropping the message. Only enforced when the registry knows the
        # target's compute location (validate_permissions=True + registry).
        target_compute = getattr(target, "compute_id", None)
        if target_compute:
            raise AgentMessagingError(
                f"Target session '{to_session_id}' lives on compute "
                f"'{target_compute}'; cross-host messaging is not yet "
                f"supported. Inboxes are per-host JSONL files. Track "
                f"progress in the qBraid roadmap."
            )

    msg = AgentMessage(
        from_session=from_session_id,
        to_session=to_session_id,
        text=text,
        type=MessageType(message_type),
    )

    inbox = _inbox_path(to_session_id)
    os.makedirs(str(inbox.parent), exist_ok=True)

    with _inbox_lock(to_session_id):
        with open(inbox, "a", encoding="utf-8") as f:
            f.write(json.dumps(msg.model_dump(mode="json")) + "\n")

    return msg


def read_inbox(
    session_id: str,
    unread_only: bool = False,
    limit: int = 50,
) -> list[AgentMessage]:
    """Read messages from a session's inbox.

    Args:
        session_id: The session whose inbox to read.
        unread_only: If *True*, return only messages with ``read=False``.
        limit: Maximum number of messages to return (most recent).

    Returns:
        List of ``AgentMessage`` objects, most recent last.
    """
    inbox = _inbox_path(session_id)
    if not inbox.exists():
        return []

    messages: list[AgentMessage] = []
    try:
        with open(inbox, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    data = json.loads(line)
                    messages.append(AgentMessage.model_validate(data))
                except (json.JSONDecodeError, Exception):
                    continue
    except OSError as exc:
        logger.debug("Error reading inbox for %s: %s", session_id, exc)
        return []

    if unread_only:
        messages = [m for m in messages if not m.read]

    return messages[-limit:]


def mark_read(
    session_id: str,
    message_ids: Optional[list[str]] = None,
) -> int:
    """Mark messages in a session's inbox as read.

    Args:
        session_id: The session whose inbox to update.
        message_ids: Specific message IDs to mark. If *None*, all messages
            are marked as read.

    Returns:
        Number of messages that were marked as read.
    """
    inbox = _inbox_path(session_id)
    if not inbox.exists():
        return 0

    # Whole read-modify-write cycle is inside the lock so a concurrent append
    # from send_message can't land between our read and rewrite (which would
    # be silently dropped when we truncate + rewrite the file).
    with _inbox_lock(session_id):
        messages: list[AgentMessage] = []
        try:
            with open(inbox, "r", encoding="utf-8") as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        data = json.loads(line)
                        messages.append(AgentMessage.model_validate(data))
                    except (json.JSONDecodeError, Exception):
                        continue
        except OSError as exc:
            logger.debug("Error reading inbox for mark_read %s: %s", session_id, exc)
            return 0

        count = 0
        for msg in messages:
            if msg.read:
                continue
            if message_ids is None or msg.id in message_ids:
                msg.read = True
                count += 1

        if count > 0:
            try:
                with open(inbox, "w", encoding="utf-8") as f:
                    for msg in messages:
                        f.write(json.dumps(msg.model_dump(mode="json")) + "\n")
            except OSError as exc:
                logger.debug("Error writing inbox for mark_read %s: %s", session_id, exc)
                return 0

    return count


def watch_inbox(
    session_id: str,
    poll_interval: float = TRANSCRIPT_POLL_INTERVAL_S,
) -> Generator[AgentMessage, None, None]:
    """Watch a session's inbox for new messages, yielding them as they arrive.

    Tracks messages by ID (not byte offset) so a concurrent ``mark_read``
    rewriting the file does NOT invalidate our position. The previous
    byte-offset implementation silently dropped messages that landed after
    a ``mark_read`` — the offset pointed into the middle of the rewritten
    stream and the trailing appends were skipped. Reproduced under bursty
    ``inbox --follow`` where the CLI mark_read's each yielded message.

    Runs indefinitely until the caller breaks out of the generator.

    Args:
        session_id: The session whose inbox to watch.
        poll_interval: Seconds between file polls.

    Yields:
        New ``AgentMessage`` objects as they are appended to the inbox.
    """
    inbox = _inbox_path(session_id)

    # Skip messages that existed at watch-start time — a follower is
    # interested in what arrives from NOW on, not the backlog.
    seen: set[str] = set()
    if inbox.exists():
        for msg in read_inbox(session_id, limit=10_000):
            seen.add(msg.id)

    while True:
        if not inbox.exists():
            time.sleep(poll_interval)
            continue

        try:
            current = read_inbox(session_id, limit=10_000)
        except OSError as exc:
            logger.debug("Error polling inbox for %s: %s", session_id, exc)
            time.sleep(poll_interval)
            continue

        for msg in current:
            if msg.id not in seen:
                yield msg
                seen.add(msg.id)

        # Bound the seen-set to what's actually in the file so memory doesn't
        # grow if the inbox is periodically pruned or archived. A message
        # that disappears and later returns will re-yield, which is the
        # right behavior (treat re-appearance as a fresh message).
        seen = {msg.id for msg in current}

        time.sleep(poll_interval)
